1	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão', debit_card: 'Débito', cash: 'Dinheiro' };
2	
3	const printIframe = (html, id) => {
4	  const f = document.createElement('iframe');
5	  f.id = id; f.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
6	  document.body.appendChild(f);
7	  try { f.contentDocument.open(); f.contentDocument.write(html); f.contentDocument.close(); }
8	  catch { f.remove(); const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close(); } }
9	};
10	
11	export const printFichaMotoboy = (pedido, itens, cliente, restauranteNome) => {
12	  const addr = cliente?.address_json ?? {};
13	  const rua = [addr.logradouro, addr.numero].filter(Boolean).join(', ');
14	  const compl = [addr.complemento, addr.bairro].filter(Boolean).join(' — ');
15	  const cidade = [addr.cidade, addr.estado].filter(Boolean).join(' / ');
16	  const ref = addr.referencia ?? '';
17	  const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
18	  const hora = new Date(pedido.created_at).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
19	  const pgto = PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method;
20	  const isCash = pedido.payment_method === 'cash';
21	  const bc = barcodeValue(pedido.id);
22	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Ficha Motoboy #${pedido.id}</title>
23	<style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Courier New',monospace;font-size:13px;padding:10px;max-width:300px;margin:0 auto;color:#000}.c{text-align:center}.big{font-size:26px;font-weight:900;text-align:center;letter-spacing:2px;margin:6px 0}hr{border:none;border-top:1px dashed #000;margin:6px 0}.item{display:flex;gap:6px;padding:2px 0}.qty{font-weight:900;min-width:24px}.addr{font-size:12px;line-height:1.5}.bold{font-weight:700}#bc{display:block;margin:6px auto 2px;max-width:260px}@media print{button{display:none!important}}</style>
24	</head><body>
25	<div class="c bold" style="font-size:11px;letter-spacing:1px">FICHA DE ENTREGA</div>
26	<div class="c" style="font-size:12px">${restauranteNome ?? ''}</div>
27	<div class="big">PEDIDO #${pedido.id}</div>
28	<div class="c" style="font-size:11px">${hora}</div>
29	<hr/>
30	<div class="bold">${cliente?.name ?? 'Cliente'}</div>
31	${cliente?.phone_e164 ? `<div>${cliente.phone_e164}</div>` : ''}
32	<div class="addr" style="margin-top:4px">${rua ? `<div>${rua}</div>` : ''}${compl ? `<div>${compl}</div>` : ''}${cidade ? `<div>${cidade}</div>` : ''}${ref ? `<div style="font-weight:bold">Ref: ${ref}</div>` : ''}</div>
33	<hr/>
34	${itens.map((i) => `<div class="item"><span class="qty">${i.quantity}x</span><span>${i.product_name ?? `#${i.product_id}`}</span></div>`).join('')}
35	<hr/>
36	<div class="c bold" style="font-size:16px">TOTAL: ${fmt(pedido.total)}</div>
37	<div class="c">${isCash ? '<span style="font-size:13px;font-weight:bold">⚠ COBRAR NA ENTREGA</span>' : `Pago: ${pgto}`}</div>
38	<hr/>
39	<svg id="bc"></svg>
40	<div class="c" style="font-size:10px;letter-spacing:1px;margin-top:2px">ESCANEIE PARA CONFIRMAR COLETA</div>
41	<div class="c" style="font-size:10px;margin-top:6px">Impresso: ${new Date().toLocaleString('pt-BR')}</div>
42	<script>
43	function doBarcode(){
44	  if(typeof JsBarcode!=='undefined'){
45	    JsBarcode("#bc","${bc}",{format:"CODE128",width:2,height:56,displayValue:true,fontSize:13,text:"#${pedido.id}",margin:6,background:"#ffffff"});
46	  }
47	  window.print();
48	  setTimeout(()=>{try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}},2000);
49	}
50	var s=document.createElement('script');
51	s.src='https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
52	s.onload=doBarcode;
53	s.onerror=function(){document.getElementById('bc').style.display='none';doBarcode()};
54	document.head.appendChild(s);
55	</script>
56	</body></html>`;
57	  printIframe(html, `motoboy-frame-${pedido.id}-${Date.now()}`);
58	};
59	
60	export const barcodeValue = (id) => String(id).padStart(8, '0');
61	
62	export const getPrinterName = () => localStorage.getItem('kitchen_printer_name') ?? '';
63	export const setPrinterName = (name) => localStorage.setItem('kitchen_printer_name', name);
64	
65	const showPrinterToast = (printerName) => {
66	  const existing = document.getElementById('printer-toast');
67	  if (existing) existing.remove();
68	  const toast = document.createElement('div');
69	  toast.id = 'printer-toast';
70	  toast.innerHTML = `🖨️ Selecione <strong>"${printerName}"</strong> na caixa de impressão`;
71	  toast.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#1A1A1A;color:#FFD700;padding:12px 22px;border-radius:14px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 24px rgba(0,0,0,0.6);white-space:nowrap';
72	  document.body.appendChild(toast);
73	  setTimeout(() => toast.remove(), 5000);
74	};
75	
76	/**
77	 * Prints comanda using a hidden iframe (avoids popup blockers — works from setInterval/auto-print).
78	 * If printerHint (name) is set, shows a toast reminding which printer to select.
79	 */
80	export const printComanda = (pedido, itens, restauranteNome, printerHint) => {
81	  const hint = printerHint ?? getPrinterName();
82	  if (hint) showPrinterToast(hint);
83	
84	  const bc = barcodeValue(pedido.id);
85	  const hora = new Date(pedido.created_at).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
86	  const clienteNome = pedido.customers?.name ?? (pedido.cliente?.name ?? '');
87	  const pgto = PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method;
88	  const isCash = pedido.payment_method === 'cash';
89	
90	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Comanda #${pedido.id}</title>
91	<style>
92	*{margin:0;padding:0;box-sizing:border-box}
93	body{font-family:'Courier New',monospace;font-size:14px;padding:12px;color:#000;max-width:300px;margin:0 auto}
94	.center{text-align:center;display:block}
95	.big{font-size:30px;font-weight:900;text-align:center;letter-spacing:3px;margin:8px 0}
96	.rest{font-size:16px;font-weight:bold;text-align:center;margin-bottom:4px}
97	hr{border:none;border-top:1px dashed #000;margin:8px 0}
98	.item{display:flex;gap:8px;padding:3px 0;font-size:15px}
99	.qty{font-weight:900;min-width:28px}
100	.foot{font-size:11px;text-align:center;margin-top:6px}
101	#barcode{display:block;margin:8px auto 4px;max-width:260px}
102	@media print{button{display:none!important}}
103	</style></head><body>
104	<div class="rest">${restauranteNome ?? 'RESTAURANTE'}</div>
105	<div class="center" style="font-size:11px;letter-spacing:1px">COMANDA DE COZINHA</div>
106	<hr/>
107	<div class="big">PEDIDO #${pedido.id}</div>
108	<div class="center" style="font-size:13px">${hora}</div>
109	${clienteNome ? `<div class="center" style="font-size:12px;margin-top:2px;font-weight:bold">${clienteNome}</div>` : ''}
110	<hr/>
111	${itens.map((i) => `<div class="item"><span class="qty">${i.quantity}x</span><span>${i.product_name ?? `Produto #${i.product_id}`}</span></div>`).join('')}
112	<hr/>
113	<div class="center" style="font-size:13px">Pgto: <b>${pgto}</b>${isCash ? ' &nbsp;⚠ COBRAR' : ''}</div>
114	<hr/>
115	<svg id="barcode"></svg>
116	<div style="text-align:center;margin:6px 0 2px">
117	  <img src="https://api.qrserver.com/v1/create-qr-code/?size=110x110&data=${bc}&qzone=1" width="110" height="110" alt="QR #${pedido.id}" style="display:inline-block" />
118	  <div style="font-size:10px;letter-spacing:1px;margin-top:2px">SCAN MOTOBOY</div>
119	</div>
120	<div class="foot">Impresso: ${new Date().toLocaleString('pt-BR')}</div>
121	<script>
122	function doBarcode(){
123	  if(typeof JsBarcode!=='undefined'){
124	    JsBarcode("#barcode","${bc}",{format:"CODE128",width:2,height:56,displayValue:true,fontSize:13,text:"#${pedido.id}",margin:6,background:"#ffffff"});
125	  }
126	  window.print();
127	  try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
128	}
129	var s=document.createElement('script');
130	s.src='https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
131	s.onload=doBarcode;
132	s.onerror=function(){document.getElementById('barcode').style.display='none';doBarcode()};
