142	  document.body.appendChild(iframe);
143	
144	  try {
145	    iframe.contentDocument.open();
146	    iframe.contentDocument.write(html);
147	    iframe.contentDocument.close();
148	  } catch {
149	    // cross-origin fallback (shouldn't happen for same-origin but just in case)
150	    iframe.remove();
151	    const w = window.open('', '_blank', 'width=440,height=680');
152	    if (w) { w.document.write(html); w.document.close(); }
153	  }
154	};
