25	  const [empresa, setEmpresa] = useState(null);
26	
27	  useEffect(() => {
28	    getMinhaEmpresa().then((d) => setEmpresa(d?.empresa ?? null)).catch(() => {});
29	  }, []);
30	
31	  const copiarLink = async (url) => {
32	    try {
33	      await navigator.clipboard.writeText(url);
